// tests/secrets.test.ts
import { describe, it, expect } from 'vitest';
import { SECRETS_VERSION, maskSecret } from '../src/secrets.js';

describe('secrets 模块', () => {
  it('模块版本号存在', () => {
    expect(SECRETS_VERSION).toBe(1);
  });
});

describe('maskSecret', () => {
  it('默认保留最后 4 个字符，其余替换为星号', () => {
    expect(maskSecret('12345678')).toBe('****5678');
  });

  it('长度恰好为 visibleEnd + 2 时进行掩码', () => {
    expect(maskSecret('123456')).toBe('**3456');
  });

  it('长度短于 visibleEnd + 2 时原样返回', () => {
    expect(maskSecret('12345')).toBe('12345');
  });

  it('空字符串原样返回', () => {
    expect(maskSecret('')).toBe('');
  });

  it('自定义 visibleEnd 参数', () => {
    expect(maskSecret('12345678', 2)).toBe('******78');
  });

  it('自定义 visibleEnd 下短于 visibleEnd + 2 时原样返回', () => {
    expect(maskSecret('123', 2)).toBe('123');
  });
});

